def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    prev_bids = []
    max_prev = 0.0
    min_prev = None
    cindy_like = False
    aggressive_count = 0

    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(bid)
                if bid > max_prev:
                    max_prev = bid
                if min_prev is None or bid < min_prev:
                    min_prev = bid
                if bid >= 110:
                    cindy_like = True
                if bid >= 78:
                    aggressive_count += 1

    if not alive:
        return min(budget, 18.0)

    likely_units = int(supply / WATER_REQ)
    if likely_units < 1:
        likely_units = 1

    urgent = hp <= 3 or no_water >= 2
    pressured = hp <= 5 or no_water >= 1

    if min_prev is None:
        if urgent:
            return min(budget, 84.0)
        if likely_units >= 2:
            return min(budget, 52.0)
        return min(budget, 38.0)

    if cindy_like and not urgent:
        if likely_units >= 2:
            base = 79.5
        else:
            base = 22.0 if hp >= 6 and no_water == 0 else 81.0
        if aggressive_count <= 1:
            base = max(base, 55.0)
        return min(budget, base)

    target = max_prev + 1.5

    if likely_units >= 2:
        target -= 6.0
    if len(alive) <= 2:
        target -= 5.0
    if pressured:
        target += 4.0
    if urgent:
        target += 8.0
    if hp >= 8 and no_water == 0 and max_prev >= 84:
        target -= 12.0

    if max_prev >= 110 and urgent:
        target = 112.0
    elif max_prev >= 90 and not urgent:
        target = min(target, 60.0)

    floor_bid = 18.0
    if pressured:
        floor_bid = 48.0
    if urgent:
        floor_bid = 78.0

    bid = max(floor_bid, target)

    if bid > 120.0:
        bid = 120.0
    if budget < bid:
        if urgent:
            return max(0.0, budget)
        return max(0.0, min(budget, floor_bid))
    return max(0.0, bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    my_hp = float(my_status.get('hp', 0.0))
    my_budget = float(my_status.get('budget', 0.0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    alive = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive.append((oid, o))

    if not alive:
        return max(0.0, min(my_budget, DAILY_SALARY * 0.4))

    # Inspect yesterday bids from immediate previous_trace only
    prev_bids = []
    for oid, o in alive:
        prev = o.get('previous_trace', {})
        if isinstance(prev, dict) and prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev['bid']))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Estimate how many full water units supply can support (per allocation unit = WATER_REQ)
    # Use int() for safety.
    capacity_units = int(supply / float(WATER_REQ))

    # Base aggressiveness: if supply is tight or we are close to death, bid more.
    tight_supply = supply <= float(WATER_REQ) * 1.2 or capacity_units <= 1

    # If Cindy likely dominates (very high previous bid), we avoid bidding near her unless necessary.
    cindy_like = highest_prev_bid >= DAILY_SALARY * 0.9

    if my_hp <= 2.0 or my_no_water_days >= 2:
        # Emergency: bid to secure water.
        target = DAILY_SALARY * (0.85 if cindy_like else 0.75)
    elif tight_supply:
        target = DAILY_SALARY * (0.65 if cindy_like else 0.55)
    else:
        # Normal: bid enough to beat low/medium bidders, but not to match the top.
        target = DAILY_SALARY * (0.45 if cindy_like else 0.55)

    # If yesterday's highest bid was not extreme, try to slightly undercut.
    if highest_prev_bid > 0 and highest_prev_bid < DAILY_SALARY * 0.9:
        target = min(target, highest_prev_bid + 10.0)

    # Clamp by budget
    bid = max(0.0, min(my_budget, target))

    # Small day-based modulation to reduce tie risk
    if day % 2 == 1:
        bid = bid * 0.98

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    supply_pressure_factor = 1.0
    available_water_units = int(day_context['supply'] // WATER_REQ)
    total_competitors = num_alive_opponents + 1

    if available_water_units < total_competitors:
        supply_pressure_factor = 1.15
    elif available_water_units >= total_competitors * 1.5:
        supply_pressure_factor = 0.9

    bid_amount = 0.0

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        if highest_prev_bid >= DAILY_SALARY * 0.85:
            if my_status['hp'] > 3:
                bid_amount = DAILY_SALARY * 0.3
            else:
                bid_amount = DAILY_SALARY * 0.95
        else:
            bid_amount = max(DAILY_SALARY * 0.5, highest_prev_bid + 1.5)
    else:
        if my_status['hp'] <= 2 or my_status['no_water_days'] > 0:
            bid_amount = DAILY_SALARY * 0.9
        else:
            bid_amount = DAILY_SALARY * 0.55

    bid_amount *= supply_pressure_factor

    if my_status['hp'] <= 2:
        bid_amount = max(bid_amount, DAILY_SALARY * 0.9)
    elif my_status['no_water_days'] > 0:
        bid_amount = max(bid_amount, DAILY_SALARY * 0.85)

    if day_context['day'] >= EPISODE_DAYS - 2:
        if my_status['budget'] > DAILY_SALARY * 1.5:
            bid_amount = max(bid_amount, DAILY_SALARY * 0.99)
        elif my_status['hp'] <= 4:
            bid_amount = max(bid_amount, DAILY_SALARY * 0.95)

    final_bid = min(my_status['budget'], bid_amount)
    return max(0.0, final_bid)

